-- ------------------------------------------------------------
-- 19. ATTENDANCE (last 14 working days for each active employee)
-- ------------------------------------------------------------
INSERT INTO hr_attendance (id, employee_id, attendance_date, check_in, check_out, status, working_minutes, overtime_minutes, late_minutes, early_departure_minutes, organization_id, created_by)
SELECT
  gen_random_uuid(),
  e.id,
  d.day::date,
  (d.day::date + CASE WHEN e.work_mode = 'remote' THEN TIME '08:00' ELSE TIME '09:00' END)::timestamptz,
  (d.day::date + CASE WHEN e.work_mode = 'remote' THEN TIME '17:00' ELSE TIME '18:00' END)::timestamptz,
  CASE
    WHEN (extract(dow FROM d.day::date) IN (0,6)) THEN 'absent'
    WHEN d.day::date = CURRENT_DATE THEN 'present'
    WHEN (e.employee_code = 'EMP-004' AND d.day::date = CURRENT_DATE - 2) THEN 'late'
    ELSE 'present'
  END,
  CASE WHEN extract(dow FROM d.day::date) IN (0,6) THEN 0 ELSE 480 END,
  0,
  CASE WHEN (e.employee_code = 'EMP-004' AND d.day::date = CURRENT_DATE - 2) THEN 30 ELSE 0 END,
  0,
  '10000000-0000-0000-0000-00000000000a',
  '00000000-0000-0000-0000-00000000000a'
FROM hr_employees e
CROSS JOIN generate_series(CURRENT_DATE - 13, CURRENT_DATE, interval '1 day') AS d(day)
WHERE e.employment_status = 'active'
ON CONFLICT (employee_id, attendance_date) DO NOTHING;

